var i=`1317-asado-uruguayo`;var s=`world-1317`;var t=`UY`;var o=`south-america`;var a=4;var n=147;var u={en:`Asado Uruguayo`,ua:`Асадо по-уругвайськи`};var g={en:`Asado Uruguayo is a dish from Uruguay featuring beef short ribs, pork ribs, fresh pork sausage, chimichurri. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Асадо по-уругвайськи, страва кухні країни Уругвай з такими основними складниками: короткі яловичі ребра, свинячі ребра, сира свиняча ковбаса, чімічурі. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 65 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 65 хвилин.`,t:[`marinating`],m:65,i:[[`beef-short-ribs`,1100,`g`],[`pork-ribs`,700,`g`],[`table-salt`,12,`g`]]},{en:`Grill over medium-high heat for about 65 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 65 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:65,i:[[`fresh-pork-sausage`,520,`g`]]},{en:`Rest the cooked meat loosely covered for about 12 minutes before slicing to retain juices.`,ua:`Дайте готовому м’ясу відпочити під нещільним накриттям приблизно 12 хвилин перед нарізанням, щоб зберегти сік.`,t:[`carryover-cooking`],m:12,i:[]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`chimichurri`,170,`g`],[`red-onion`,200,`g`]]}];var h={slug:i,id:s,country:`UY`,region:o,servings:4,minutes:147,title:u,text:g,steps:d};export{t as country,h as default,s as id,n as minutes,o as region,a as servings,i as slug,d as steps,g as text,u as title};